den" name="delta" value="1"><input type="hidden" name="product_id" value="<?=$r['id']?>"><input type="hidden" name="return_to" value="index.php#cart"><button>+</button></form></div></div><?php endforeach;?><h3 id="checkout">اطلاعات تحویل</h3><?php if(!$state['open']):?><div class="notice"><?=e($state['message'])?></div><?php endif;?><form method="post" class="checkout"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input type="hidden" name="action" value="checkout"><label>نام<input name="name" required value="<?=e($_SESSION['checkout_name']??'')?>"></label><label>موبایل<input name="phone" required pattern="09[0-9]{9}" value="<?=e($_SESSION['checkout_phone']??'')?>"></label><label class="wide">آدرس<textarea name="address" required><?=e($_SESSION['checkout_address']??'')?></textarea></label><div class="locbox wide"><input type="hidden" name="delivery_lat" id="delivery_lat"><input type="hidden" name="delivery_lng" id="delivery_lng"><input type="hidden" name="delivery_accuracy" id="delivery_accuracy"><div class="lochead"><div><b>📍 لوکیشن تحویل روی نقشه</b><span class="muted">روی خیابان یا کوچه موردنظر بزنید؛ لازم نیست لوکیشن فعلی خودتان باشد.</span></div></div><div id="deliveryMap" class="delivery-map" aria-label="نقشه انتخاب محل تحویل"></div><div class="locactions"><button type="button" class="btn pale" id="getLocation">موقعیت فعلی من</button><button type="button" class="btn" id="saveMapLocation">ثبت این نقطه</button><button type="button" class="btn pale" id="clearLocation">پاک کردن لوکیشن</button></div><div id="locationStatus" class="locstatus">پین را روی محل تحویل بگذارید و «ثبت این نقطه» را بزنید.</div></div><label>محدوده ارسال<select name="zone_id" id="zone"><?php foreach($zones as $z):?><option value="<?=$z['id']?>" data-fee="<?=$z['fee']?>" data-min="<?=$z['min_order']?>" data-eta="<?=e($z['eta'])?>"><?=e($z['name'])?> · <?=toman($z['fee'])?></option><?php endforeach;?></select></label><label class="wide">کد تخفیف (اختیاری)<input name="coupon_code" autocomplete="off" placeholder="مثلاً WELCOME"></label><label>زمان تحویل<select name="slot"><option>اولین زمان ممکن</option><option>۱۰ تا ۱۲</option><option>۱۲ تا ۱۴</option><option>۱۶ تا ۱۸</option><option>۱۸ تا ۲۰</option><option>۲۰ تا ۲۲</option></select></label><div id="hint" class="hint wide"></div><button id="submit" class="btn wide" <?=$state['open']?'':'disabled'?>><?=$state['open']?'ثبت سفارش':'فروشگاه بسته است'?></button></form><?php else:?><p class="muted">سبد خرید خالی است.</p><?php endif;?></section></main><?php if($count):?><div class="sticky"><b><?=$count?> کالا · <?=toman($sub)?></b><a href="#cart">سبد خرید</a></div><?php endif;?><footer>سوپرمارکت طهران · بهارستان اصفهان</footer><script>(function(){const z=document.getElementById('zone'),h=document.getElementById('hint'),b=document.getElementById('submit'),sub=<?=$sub?>;function u(){if(!z)return;const o=z.options[z.selectedIndex],f=+(o.dataset.fee||0),m=+(o.dataset.min||0),eta=o.dataset.eta||'';h.textContent='هزینه ارسال: '+f.toLocaleString('fa-IR')+' تومان · جمع کل: '+(sub+f).toLocaleString('fa-IR')+' تومان'+(m?' · حداقل خرید: '+m.toLocaleString('fa-IR')+' تومان':'')+(eta?' · '+eta:'');if(b&&m>sub){b.disabled=true;b.textContent='حداقل خرید کامل نشده';}else if(b&&<?=$state['open']?'true':'false'?>){b.disabled=false;b.textContent='ثبت سفارش · '+(sub+f).toLocaleString('fa-IR')+' تومان';}}if(z){z.onchange=u;u();}})();</script><script src="https://unpkg.com/leaflet@1.9.4/dist/leaflet.js" crossorigin=""></script><script>(()=>{const mapEl=document.getElementById('deliveryMap'),geoBtn=document.getElementById('getLocation'),saveBtn=document.getElementById('saveMapLocation'),clearBtn=document.getElementById('clearLocation'),st=document.getElementById('locationStatus'),la=document.getElementById('delivery_lat'),ln=document.getElementById('delivery_lng'),ac=document.getElementById('delivery_accuracy');if(!mapEl||typeof L==='undefined')return;const home=[32.48814,51.773119];let pending={lat:home[0],lng:home[1],acc:null};const map=L.map(mapEl,{zoomControl:true,attributionControl:true}).setView(home,14);L.tileLayer('map_tile.php?z={z}&x={x}&y={y}',{maxZoom:19,minZoom:3,attribution:'&copy; OpenStreetMap contributors'}).addTo(map);const icon=L.divIcon({className:'delivery-pin',html:'<div style="font-size:34px;line-height:34px;transform:translate(-5px,-15px)">📍</div>',iconSize:[24,36],iconAnchor:[12,34]});const marker=L.marker(home,{draggable:true,icon}).addTo(map);function choose(lat,lng,acc=null,zoom=false){pending={lat:+lat,lng:+lng,acc:acc==null?null:Math.max(0,Math.round(+acc||0))};marker.setLatLng([pending.lat,pending.lng]);if(zoom)map.setView([pending.lat,pending.lng],17);st.className='locstatus';st.textContent='نقطه انتخاب شد؛ اگر درست است «ثبت این نقطه» را بزنید.';}map.on('click',e=>choose(e.latlng.lat,e.latlng.lng,null,false));marker.on('dragend',()=>{const p=marker.getLatLng();choose(p.lat,p.lng,null,false);});saveBtn.addEventListener('click',()=>{la.value=pending.lat.toFixed(7);ln.value=pending.lng.toFixed(7);ac.value=pending.acc??'';st.className='locstatus ok';st.textContent='✅ لوکیشن تحویل ثبت شد. می‌توانید قبل از ثبت سفارش دوباره آن را تغییر دهید.';});clearBtn.addEventListener('click',()=>{la.value='';ln.value='';ac.value='';pending={lat:home[0],lng:home[1],acc:null};marker.setLatLng(home);map.setView(home,14);st.className='locstatus';st.textContent='لوکیشن پاک شد؛ یک نقطه دیگر روی نقشه انتخاب کنید.';});let accuracyCircle=null;function stopAccuracyCircle(){if(accuracyCircle){map.removeLayer(accuracyCircle);accuracyCircle=null;}}function showCurrentPosition(pos){const lat=Number(pos.coords.latitude),lng=Number(pos.coords.longitude),acc=Math.max(1,Math.round(Number(pos.coords.accuracy||0)));choose(lat,lng,acc,true);stopAccuracyCircle();accuracyCircle=L.circle([lat,lng],{radius:acc,color:'#1976d2',weight:1,fillColor:'#64b5f6',fillOpacity:.13}).addTo(map);geoBtn.disabled=false;geoBtn.textContent='موقعیت فعلی من';if(acc<=80){st.className='locstatus ok';st.textContent='✅ موقعیت گوشی پیدا شد · دقت حدود '+acc.toLocaleString('fa-IR')+' متر. اگر درست است «ثبت این نقطه» را بزنید.';}else{st.className='locstatus warn';st.textContent='⚠️ موقعیت گوشی پیدا شد اما دقت آن حدود '+acc.toLocaleString('fa-IR')+' متر است. سنجاق جابه‌جا شد؛ در صورت نیاز آن را دستی روی محل دقیق تحویل ببرید.';}}function showGeoError(err){geoBtn.disabled=false;geoBtn.textContent='موقعیت فعلی من';st.className='locstatus warn';if(err&&err.code===1)st.textContent='اجازه دسترسی به موقعیت برای Chrome داده نشده است. مجوز Location را برای این سایت فعال کنید یا نقطه را دستی انتخاب کنید.';else if(err&&err.code===2)st.textContent='گوشی نتوانست موقعیت فعلی را پیدا کند. GPS/Location را روشن کنید و دوباره بزنید، یا نقطه را دستی انتخاب کنید.';else if(err&&err.code===3)st.textContent='دریافت موقعیت طول کشید و متوقف شد. دوباره امتحان کنید یا نقطه را دستی انتخاب کنید.';else st.textContent='موقعیت فعلی دریافت نشد. می‌توانید محل تحویل را دستی روی نقشه انتخاب کنید.';}geoBtn.addEventListener('click',()=>{if(!navigator.geolocation){showGeoError({code:0});return;}geoBtn.disabled=true;geoBtn.textContent='در حال پیدا کردن موقعیت…';st.className='locstatus';st.textContent='در حال دریافت موقعیت گوشی…';navigator.geolocation.getCurrentPosition(showCurrentPosition,showGeoError,{enableHighAccuracy:true,timeout:15000,maximumAge:0});});setTimeout(()=>map.invalidateSize(),100);})();</script><script>(()=>{if('serviceWorker' in navigator)window.addEventListener('load',()=>navigator.serviceWorker.register('sw.js',{scope:'/tehran/'}).catch(()=>{}));let p=null;const b=document.getElementById('pwaInstall');window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();p=e;if(b)b.hidden=false;});if(b)b.addEventListener('click',async()=>{if(!p)return;p.prompt();await p.userChoice;p=null;b.hidden=true;});window.addEventListener('appinstalled',()=>{if(b)b.hidden=true;});})();</script></body></html>